<?php
session_start();require_once __DIR__.'/../config/config.php';
$bookId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$bookId){http_response_code(404);exit('ไม่พบสินค้า');}
$bookStmt=$pdo->prepare("SELECT book_id,title,author FROM books WHERE book_id=? AND status<>'hidden'");$bookStmt->execute([$bookId]);$book=$bookStmt->fetch(PDO::FETCH_ASSOC);if(!$book){http_response_code(404);exit('ไม่พบสินค้า');}
$page=max(1,(int)($_GET['page']??1));$perPage=10;$countStmt=$pdo->prepare('SELECT COUNT(*) FROM book_reviews WHERE book_id=?');$countStmt->execute([$bookId]);$total=(int)$countStmt->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$stmt=$pdo->prepare("SELECT r.*,COALESCE(NULLIF(u.display_name,''),u.email,'สมาชิกวนวรรณ') reviewer_name,u.profile_image FROM book_reviews r LEFT JOIN users u ON u.user_id=r.user_id WHERE r.book_id=? ORDER BY r.created_at DESC LIMIT $perPage OFFSET $offset");$stmt->execute([$bookId]);$reviews=$stmt->fetchAll(PDO::FETCH_ASSOC);
$avgStmt=$pdo->prepare('SELECT AVG(rating) FROM book_reviews WHERE book_id=?');$avgStmt->execute([$bookId]);$average=(float)$avgStmt->fetchColumn();
function reviewerAvatar(?string $value):?string{if(!$value)return null;if(preg_match('#^https?://#i',$value))return $value;$value=ltrim($value,'/');return str_starts_with($value,'uploads/')?'/pages/'.$value:'/assets/image/'.$value;}
ob_start(function(string $html) use($reviews):string{$index=0;return preg_replace_callback('#(<article class="review">.*?)(</article>)#s',function($match)use(&$index,$reviews){$review=$reviews[$index++]??null;if(!$review||empty($review['seller_reply']))return$match[0];$reply='<div style="margin-top:12px;padding:12px 15px;border-left:3px solid #d586a4;border-radius:8px;background:#fff5f8"><strong style="color:#a34f70">คำตอบจากร้าน</strong><p style="margin:6px 0">'.nl2br(htmlspecialchars($review['seller_reply'])).'</p><small style="color:#998782">'.date('d/m/Y H:i',strtotime($review['seller_reply_at'])).'</small></div>';return$match[1].$reply.$match[2];},$html)??$html;});
?>
<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>รีวิว <?=htmlspecialchars($book['title'])?></title><link rel="stylesheet" href="../assets/css/styles.css"><style>*{box-sizing:border-box}.page{max-width:980px;margin:auto;padding:42px 24px 90px}.back{color:var(--secondary-color)}h1{color:var(--secondary-color);margin-bottom:5px}.summary{display:flex;gap:12px;align-items:center;color:#8c756d;margin-bottom:25px}.score{font-size:28px;font-weight:700;color:#d69428}.review{display:flex;gap:15px;padding:22px 0;border-bottom:1px solid #eaded8}.avatar{width:48px;height:48px;flex:0 0 48px;border-radius:50%;object-fit:cover;background:#f5dce5;display:grid;place-items:center;color:#b85e7e;font-weight:700}.review-head{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.stars{color:#dfa027;letter-spacing:2px}.date{color:#998b85;font-size:13px}.review p{white-space:pre-wrap;line-height:1.75}.pages{display:flex;gap:8px;margin-top:28px}.pages a{padding:8px 13px;border:1px solid #dccdc7;border-radius:8px;text-decoration:none;color:var(--secondary-color)}.pages a.active{background:var(--secondary-color);color:#fff}</style></head><body><?php require __DIR__.'/../components/header.php';?><main class="page"><a class="back" href="/pages/book_detail.php?id=<?=$bookId?>">‹ กลับไปหน้าสินค้า</a><h1>รีวิวทั้งหมดของ “<?=htmlspecialchars($book['title'])?>”</h1><div class="summary"><span class="score"><?=number_format($average,1)?> ★</span><span>จาก <?=number_format($total)?> รีวิวที่ซื้อสินค้าจริง</span></div><?php if(!$reviews):?><p>สินค้านี้ยังไม่มีรีวิว</p><?php else:foreach($reviews as $r):?><article class="review"><?php if($avatar=reviewerAvatar($r['profile_image'])):?><img class="avatar" src="<?=htmlspecialchars($avatar)?>" alt=""><?php else:?><div class="avatar"><?=htmlspecialchars(mb_substr($r['reviewer_name'],0,1))?></div><?php endif;?><div><div class="review-head"><strong><?=htmlspecialchars($r['reviewer_name'])?></strong><span class="stars"><?=str_repeat('★',(int)$r['rating']).str_repeat('☆',5-(int)$r['rating'])?></span><span class="date"><?=date('d/m/Y',strtotime($r['created_at']))?></span></div><p><?=htmlspecialchars($r['review_text']?:'ให้คะแนนสินค้าโดยไม่ได้เขียนข้อความเพิ่มเติม')?></p></div></article><?php endforeach;endif;?><?php if($pages>1):?><nav class="pages"><?php for($i=1;$i<=$pages;$i++):?><a class="<?=$i===$page?'active':''?>" href="?id=<?=$bookId?>&page=<?=$i?>"><?=$i?></a><?php endfor;?></nav><?php endif;?></main><?php require __DIR__.'/../components/footer.php';?></body></html>
